import pylops

nt = 301
dt = 0.004
rng = np.random.default_rng(3)

# asymmetric (minimum-phase-like) wavelet
tw = np.arange(41) * dt
h = np.exp(-tw / 0.02) * np.sin(2 * np.pi * 25 * tw)
nh = len(h)

def forward(x):
    # causal convolution, keep the first nt samples
    return np.convolve(x, h, mode="full")[:nt]

def adjoint(y):
    # adjoint of causal convolution = correlation with reversed wavelet
    # extract nt samples from the beginning of the full correlation
    return np.convolve(y, h[::-1], mode="full")[:nt]

Op = pylops.FunctionOperator(forward, adjoint, nt, nt)

x = np.zeros(nt)
x[[50, 120, 125, 200]] = [1.0, -0.6, 0.4, 0.8]
y = Op @ x + 1e-4 * rng.standard_normal(nt)

# Test adjoint correctness: <Ax, y> should equal <x, A*y>
x_test = rng.standard_normal(nt)
y_test = rng.standard_normal(nt)
lhs = np.dot(Op @ x_test, y_test)
rhs = np.dot(x_test, Op.H @ y_test)
print(f"Adjoint test: <Ax,y> = {lhs:.6e}, <x,A*y> = {rhs:.6e}, ratio = {lhs/rhs:.6f}")

xinv = pylops.optimization.basic.lsqr(Op, y, niter=200, damp=1e-4)[0]
print("relative error:", np.linalg.norm(xinv - x) / np.linalg.norm(x))
